with flattened as (select id, customer_id, coupon_codes, inline(items) from carts) select s.id, s.customer_id, s.product_id, s.price, s.promo, case when promo rlike '^(BUNDLE|WELCOME5)$' then 'EXTENDED' else 'PRIORITY' end as promo_zone, (select max(x.balance) from accounts x where x.customer_id = s.customer_id) as max_account_balance from flattened s order by max_account_balance desc nulls first, promo
